  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Edaravone, a closely related pyrazolone, had an absolute oral bioavailability of 57.3% in Japanese subjects after a 105 mg oral suspension versus a 60 mg IV dose, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Clobazam, a structurally related heterocyclic drug, is rapidly and extensively absorbed with an oral bioavailability of approximately 87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Mavacamten, another heterocyclic drug, has an estimated oral bioavailability of at least 85% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Fenspiride showed an absolute oral bioavailability of 90% in healthy volunteers, supporting high F for small heterocyclic drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an antipyrine-like pyrazolone. Direct human absolute bioavailability data for the closest analogue edaravone (57%) and high oral bioavailability for several structurally related heterocycles (clobazam ~87%, mavacamten ≥85%, fenspiride 90%) consistently support F ≥20%. No evidence suggests low oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; the closest analogue edaravone differs by N-H versus N-methyl and carbonyl position.",
    "Fasted-state-specific data are limited, though edaravone modeling was conducted under fasted conditions and the other supporting drugs are not expected to be food-sensitive enough to cross the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

